/**
 * lib/contentQuality.js
 * Detects low-value ("fallback") articles generated by
 * scripts/rewrite-article.mjs when every LLM API was unavailable/exhausted.
 * These articles reuse one of 4 fixed boilerplate templates (only the
 * sport/league label changes), which Google AdSense flags as thin /
 * duplicate content. We noindex them and drop them from the sitemap
 * instead of serving/indexing them, until they get properly rewritten.
 */

// Fixed phrases from each fallback template's intro sentence in
// scripts/rewrite-article.mjs (ARTICLE_TYPES). Only the "${label}"
// (sport/league name) varies around these, so a substring match is
// a reliable, false-positive-free signature.
const FALLBACK_SIGNATURES = [
  "يتواصل الجدل الرياضي حول آخر مستجدات",
  "حركية لافتة في المشهد الرياضي، وسط معطيات جديدة تُعيد رسم خريطة التوقعات",
  "تُطرح تساؤلات جوهرية مشروعة حول مآلات الموسم",
  "رصد فريق نبض الرياضة أبرز ما جرى في",
];

export function isFallbackText(text = "") {
  const value = String(text || "");
  return FALLBACK_SIGNATURES.some((sig) => value.includes(sig));
}

export function isLowValueArticle(article = {}) {
  if (!article) return false;
  if (isFallbackText(article.description) || isFallbackText(article.content)) {
    return true;
  }
  const wordCount = (article.content || "")
    .trim()
    .split(/\s+/)
    .filter(Boolean).length;
  return wordCount > 0 && wordCount < 300;
}
